import React from 'react';
import './Hero.css';
import hero  from '../Assets/hero.png'; // Update path as needed

const Hero = () => {
  return (
    <div className="hero">
      {/* Left Content Section */}
      <div className="hero-left">
        <p className="hero-tagline">Latest Smartphones</p>
        <h2>NEW ARRIVAL</h2>
        <h3>Ultimate Performance</h3>
        <p className="hero-description">
          Experience next-level speed, stunning design, and innovation like never before.
        </p>
        <div className="hero-buttons">
          <button className="btn-primary">Shop Now</button>
          <button className="btn-secondary">Explore More</button>
        </div>
      </div>

      {/* Right Image Section */}
      <div className="hero-right">
        <img src={hero} alt="Smartphone Mockup" />
      </div>
    </div>
  );
};

export default Hero;
